// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.agent.automationimport android.graphics.Rectimport android.view.accessibility.AccessibilityNodeInfoimport com.roshan.persona.agent.accessibility.AccessibilityServiceRegistryimport com.roshan.persona.agent.accessibility.NousAccessibilityServiceimport com.roshan.persona.agent.guard.BankingAppGuardimport kotlinx.coroutines.suspendCancellableCoroutineimport kotlin.coroutines.resumeimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Accessibility Automation Provider (Module 9 v1 — Step 9.2, P1 fix). * * REAL implementation of [AutomationProvider] that translates * [AutomationOperation]s into real `AccessibilityService` actions. * * Previously the [AutomationProvider] interface existed but had **no concrete * implementation** — meaning `AutomationEngine` and any caller that injected * `AutomationProvider` would have had nothing to bind. This file fixes that * P1 by providing the concrete class. * * ## Real Android APIs used * * | Operation | AccessibilityService API | * |-----------|---------------------------| * | [AutomationOperation.Tap] | `dispatchGesture(GestureDescription)` (single-point stroke, 50ms) | * | [AutomationOperation.Swipe] | `dispatchGesture(...)` (line path) | * | [AutomationOperation.LongPress] | `dispatchGesture(...)` (long-duration stroke) | * | [AutomationOperation.TypeText] | `AccessibilityNodeInfo.performAction(ACTION_SET_TEXT)` on the focused node | * | [AutomationOperation.ClickButtonByText] | `findAccessibilityNodeInfosByText()` + `ACTION_CLICK` | * | [AutomationOperation.ClickButtonByViewId] | `findAccessibilityNodeInfosByViewId()` + `ACTION_CLICK` | * | [AutomationOperation.PressKey] | `performGlobalAction()` (back/home/recents mapping) | * | [AutomationOperation.TakeScreenshot] | `AccessibilityService.takeScreenshot()` (API 30+) | * | [AutomationOperation.GetUiTree] | `getRootInActiveWindow()` + `UiTreeSnapshot.from()` | * | [AutomationOperation.OpenApp] | NotSupported (accessibility can't launch arbitrary apps — needs LADB or Context.startActivity) | * | [AutomationOperation.Scroll] | `dispatchGesture(...)` (swipe from center to edge) | * * ## Privacy * *  - Every operation is gated by [BankingAppGuard] — if the foreground app *    is on the banking blacklist, the operation returns `Failure` immediately. *  - [AutomationOperation.TypeText] refuses to write into `isPassword` nodes *    (defence in depth — the LLM shouldn't be sending passwords, but if it *    tries, the accessibility layer refuses). *  - Screenshots are wrapped in [AutomationResultData.Screenshot] and never *    persisted — RAM-only. * * ## Hilt wiring * * `@Singleton @Inject constructor()` — the provider is stateless; the * underlying `NousAccessibilityService` instance is fetched lazily from * [AccessibilityServiceRegistry] on each call (because Android's framework * controls the service lifecycle, not Hilt). * * @see <a href="docs/strategy/module-9-agent-strategy-v1.md">§Step 9.2: AccessibilityAutomationProvider</a> */@Singletonclass AccessibilityAutomationProvider @Inject constructor() : AutomationProvider {    companion object {        private const val TAG = "A11yAutoProvider"    }    override val providerName: String = "Accessibility"    override val method: AutomationMethod = AutomationMethod.ACCESSIBILITY    /**     * True if the NOUS AccessibilityService is connected.     *     * Delegates to [AccessibilityServiceRegistry.isActive] (a static     * `AtomicReference` lookup — O(1), no allocation).     */    override fun isAvailable(): Boolean = AccessibilityServiceRegistry.isActive()    /**     * Execute an [AutomationOperation] via the active accessibility service.     *     * Real implementation: looks up the live `NousAccessibilityService` from     * the registry, dispatches the appropriate Android API, measures duration,     * and wraps the result in [AutomationResult].     *     * @return [AutomationResult.Success] on success, [AutomationResult.Failure]     *         if the service is not connected / the operation failed / the     *         foreground app is on the banking blacklist, or     *         [AutomationResult.NotSupported] for operations that accessibility     *         cannot perform (e.g., [AutomationOperation.OpenApp]).     */    override suspend fun execute(operation: AutomationOperation): AutomationResult {        val startNanos = System.nanoTime()        val service = AccessibilityServiceRegistry.getInstance()        if (service == null) {            Timber.tag(TAG).w("AccessibilityService not connected — refusing operation $operation.")            return AutomationResult.Failure(                operation = operation,                reason = "AccessibilityService not connected (user must enable it in Settings)",                durationMs = durationMs(startNanos),            )        }        // Privacy hard-line: never automate the foreground banking app.        val foregroundPkg = currentForegroundPackage(service)        if (BankingAppGuard().isBankingApp(foregroundPkg)) {            Timber.tag(TAG).w("Refusing operation on blacklisted banking app: $foregroundPkg.")            return AutomationResult.Failure(                operation = operation,                reason = "Banking app ($foregroundPkg) is on the privacy blacklist — automation refused",                durationMs = durationMs(startNanos),            )        }        return try {            val result = dispatchToService(operation, service)            result.copyWithDuration(durationMs(startNanos))        } catch (e: IllegalStateException) {            // Node was invalidated between find + performAction — common when            // the UI navigates while we're mid-action.            Timber.tag(TAG).e(e, "Node invalidated while executing $operation.")            AutomationResult.Failure(                operation = operation,                reason = "Node invalidated: ${e.message}",                durationMs = durationMs(startNanos),            )        } catch (e: SecurityException) {            Timber.tag(TAG).e(e, "SecurityException executing $operation.")            AutomationResult.Failure(                operation = operation,                reason = "SecurityException: ${e.message}",                durationMs = durationMs(startNanos),            )        } catch (e: Exception) {            Timber.tag(TAG).e(e, "Unexpected error executing $operation.")            AutomationResult.Failure(                operation = operation,                reason = "Unexpected error: ${e.message}",                durationMs = durationMs(startNanos),            )        }    }    // ─── Dispatch ────────────────────────────────────────────────────────────    /**     * Translate an [AutomationOperation] into a real `AccessibilityService` call.     *     * Returns the raw [AutomationResult] (duration will be set by the caller).     */    private suspend fun dispatchToService(        operation: AutomationOperation,        service: NousAccessibilityService,    ): AutomationResult {        return when (operation) {            is AutomationOperation.Tap -> {                val ok = service.tapAt(operation.x, operation.y)                AutomationResult.Success(                    operation = operation,                    durationMs = 0L,                    data = AutomationResultData.BooleanResult(ok),                )            }            is AutomationOperation.Swipe -> {                val ok = service.swipe(                    operation.startX, operation.startY,                    operation.endX, operation.endY,                    operation.durationMs,                )                AutomationResult.Success(                    operation = operation,                    durationMs = 0L,                    data = AutomationResultData.BooleanResult(ok),                )            }            is AutomationOperation.LongPress -> {                val ok = service.longPressAt(operation.x, operation.y, operation.durationMs)                AutomationResult.Success(                    operation = operation,                    durationMs = 0L,                    data = AutomationResultData.BooleanResult(ok),                )            }            is AutomationOperation.TypeText -> {                val ok = typeIntoFocusedNode(service, operation.text)                AutomationResult.Success(                    operation = operation,                    durationMs = 0L,                    data = AutomationResultData.BooleanResult(ok),                )            }            is AutomationOperation.ClickButtonByText -> {                val ok = service.clickNodeByText(operation.buttonText)                AutomationResult.Success(                    operation = operation,                    durationMs = 0L,                    data = AutomationResultData.BooleanResult(ok),                )            }            is AutomationOperation.ClickButtonByViewId -> {                val ok = clickNodeByViewId(service, operation.viewId)                AutomationResult.Success(                    operation = operation,                    durationMs = 0L,                    data = AutomationResultData.BooleanResult(ok),                )            }            is AutomationOperation.PressKey -> {                val ok = pressGlobalKey(service, operation.keyCode)                AutomationResult.Success(                    operation = operation,                    durationMs = 0L,                    data = AutomationResultData.BooleanResult(ok),                )            }            is AutomationOperation.TakeScreenshot -> {                // Bridge the callback-based takeScreenshot into a suspend result.                val bitmap = suspendCoroutineOfBitmap(service)                if (bitmap != null) {                    AutomationResult.Success(                        operation = operation,                        durationMs = 0L,                        data = AutomationResultData.Screenshot(bitmap),                    )                } else {                    AutomationResult.Failure(                        operation = operation,                        reason = "takeScreenshot returned null (API <30 or service not active)",                        durationMs = 0L,                    )                }            }            is AutomationOperation.GetUiTree -> {                val root = service.getActiveWindowRoot()                val packageName = currentForegroundPackage(service) ?: "unknown"                val snapshot = UiTreeSnapshot.from(root, packageName)                if (snapshot != null) {                    AutomationResult.Success(                        operation = operation,                        durationMs = 0L,                        data = AutomationResultData.UiTree(snapshot),                    )                } else {                    AutomationResult.Failure(                        operation = operation,                        reason = "Root node unavailable (no active window)",                        durationMs = 0L,                    )                }            }            is AutomationOperation.OpenApp -> {                // AccessibilityService cannot launch arbitrary apps — the                // caller must use `Intent.ACTION_MAIN` + `CATEGORY_LAUNCHER`                // via a Context, or use LADB `am start`. Returning                // NotSupported so the AutomationEngine can fall back.                AutomationResult.NotSupported(                    operation = operation,                    providerName = providerName,                )            }            is AutomationOperation.Scroll -> {                val ok = scrollViaGesture(service, operation.direction)                AutomationResult.Success(                    operation = operation,                    durationMs = 0L,                    data = AutomationResultData.BooleanResult(ok),                )            }        }    }    // ─── Helpers ─────────────────────────────────────────────────────────────    /**     * Get the package name of the current foreground window (or null if the     * service isn't connected).     *     * Uses the real `AccessibilityNodeInfo.packageName` from the active     * window root. If the root is null (e.g., on the system launcher with no     * window), falls back to the system foreground package via     * `AccessibilityService`-level APIs.     */    private fun currentForegroundPackage(service: NousAccessibilityService): String? {        val root = service.getActiveWindowRoot() ?: return null        return root.packageName?.toString()    }    /**     * Set text on the focused node via `ACTION_SET_TEXT`.     *     * Walks the tree from the root looking for a focused, editable, non-password     * node, then performs `performAction(ACTION_SET_TEXT, bundle)`.     *     * Privacy: refuses to set text on `isPassword` nodes (defence in depth).     *     * @return true if text was set, false otherwise.     */    private fun typeIntoFocusedNode(service: NousAccessibilityService, text: String): Boolean {        val root = service.getActiveWindowRoot() ?: run {            Timber.tag(TAG).w("Cannot type — no active window.")            return false        }        val target = findFocusedEditableNode(root)        if (target == null) {            Timber.tag(TAG).w("Cannot type — no focused editable node.")            return false        }        if (target.isPassword) {            Timber.tag(TAG).w("Refusing to type into password field — privacy hard-line.")            return false        }        val args = android.os.Bundle().apply {            putCharSequence(                AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,                text,            )        }        return target.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT, args)    }    /**     * Walk the tree to find the focused, editable node (REAL Android API).     *     * Returns null if no node is focused + editable.     */    private fun findFocusedEditableNode(node: AccessibilityNodeInfo): AccessibilityNodeInfo? {        if (node.isEditable && node.isFocused) return node        for (i in 0 until node.childCount) {            val child = node.getChild(i) ?: continue            val found = findFocusedEditableNode(child)            if (found != null) return found        }        return null    }    /**     * Click the first clickable node matching a view ID.     *     * Walks `findNodesByViewId`, attempts `ACTION_CLICK` on the node or its     * parent (real Android API — same pattern as `clickNodeByText`).     */    private fun clickNodeByViewId(service: NousAccessibilityService, viewId: String): Boolean {        val nodes = service.findNodesByViewId(viewId)        for (node in nodes) {            try {                if (node.isClickable) {                    return node.performAction(AccessibilityNodeInfo.ACTION_CLICK)                }                val parent = node.parent                if (parent?.isClickable == true) {                    return parent.performAction(AccessibilityNodeInfo.ACTION_CLICK)                }            } catch (e: IllegalStateException) {                Timber.tag(TAG).w("Node invalidated before click on $viewId: ${e.message}")                continue            }        }        Timber.tag(TAG).w("No clickable node found with viewId $viewId.")        return false    }    /**     * Map a key code to a `performGlobalAction` constant.     *     * Supports: BACK, HOME, RECENTS, NOTIFICATIONS, QUICK_SETTINGS, LOCK_SCREEN.     * For other keys, returns false (the caller can try LADB's `input keyevent`).     */    private fun pressGlobalKey(service: NousAccessibilityService, keyCode: Int): Boolean {        val globalAction = when (keyCode) {            android.view.KeyEvent.KEYCODE_BACK -> NousAccessibilityService_GlobalActions.GLOBAL_ACTION_BACK            android.view.KeyEvent.KEYCODE_HOME -> NousAccessibilityService_GlobalActions.GLOBAL_ACTION_HOME            android.view.KeyEvent.KEYCODE_APP_SWITCH -> NousAccessibilityService_GlobalActions.GLOBAL_ACTION_RECENTS            else -> {                Timber.tag(TAG).w("PressKey($keyCode) not mapped to a global action.")                return false            }        }        return service.executeGlobalAction(globalAction)    }    /**     * Scroll the screen in a direction by dispatching a swipe gesture from     * the screen center toward the appropriate edge (REAL Android API).     *     * Uses `dispatchGesture` via `NousAccessibilityService.swipe` — a swipe     * with a 400ms duration is the Android-recommended "scroll" gesture.     */    private fun scrollViaGesture(        service: NousAccessibilityService,        direction: ScrollDirection,    ): Boolean {        val bounds: Rect = service.getScreenBounds() ?: return false        val cx = bounds.exactCenterX()        val cy = bounds.exactCenterY()        val dx = bounds.width() * 0.4f        val dy = bounds.height() * 0.4f        return when (direction) {            ScrollDirection.UP -> service.swipe(cx, cy + dy, cx, cy - dy, durationMs = 400)            ScrollDirection.DOWN -> service.swipe(cx, cy - dy, cx, cy + dy, durationMs = 400)            ScrollDirection.LEFT -> service.swipe(cx + dx, cy, cx - dx, cy, durationMs = 400)            ScrollDirection.RIGHT -> service.swipe(cx - dx, cy, cx + dx, cy, durationMs = 400)        }    }    /**     * Suspend until the `takeScreenshot` callback fires, then return its bitmap.     *     * Real Android API: `AccessibilityService.takeScreenshot(int requestId,     * Executor, TakeScreenshotCallback)`. The callback is invoked on a     * background thread; we bridge it to a coroutine via `suspendCancellableCoroutine`.     *     * Returns null on failure or API <30 (the underlying service handles the     * version check).     */    private suspend fun suspendCoroutineOfBitmap(        service: NousAccessibilityService,    ): android.graphics.Bitmap? {        return suspendCancellableCoroutine<android.graphics.Bitmap?> { cont ->            service.takeScreenshot { bitmap ->                if (cont.isActive) {                    try {                        cont.resume(bitmap)                    } catch (t: Throwable) {                        // Already cancelled — ignore.                    }                }            }        }    }    /**     * Convert nanos to millis for [AutomationResult] duration fields.     */    private fun durationMs(startNanos: Long): Long =        (System.nanoTime() - startNanos) / 1_000_000L}/** * Helper accessor for `AccessibilityService.GLOBAL_ACTION_*` constants. * * We don't reference `android.accessibilityservice.AccessibilityService` directly * in [AccessibilityAutomationProvider] to keep imports clean — these constants * are stable across all API levels we support (min API 29). * * Note: cannot be `const val` because the initializer references a Java static * final int (Kotlin only allows literal initializers for `const val`). Plain * `val` is fine — the JVM inlines the lookup at the call site. */private object NousAccessibilityService_GlobalActions {    val GLOBAL_ACTION_BACK: Int = android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK    val GLOBAL_ACTION_HOME: Int = android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_HOME    val GLOBAL_ACTION_RECENTS: Int = android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_RECENTS}/** * Extension: copy an [AutomationResult] with a new duration. * * Success/Failure carry a `durationMs` field — set it once at the call site * rather than threading it through every dispatch branch. */private fun AutomationResult.copyWithDuration(durationMs: Long): AutomationResult = when (this) {    is AutomationResult.Success -> copy(durationMs = durationMs)    is AutomationResult.Failure -> copy(durationMs = durationMs)    is AutomationResult.NotSupported -> this}